use crate::models::{ClipboardPayload, SUPPORTED_TYPES, TEXT};
use crate::{CoreError, Result};
use regex::RegexBuilder;
use serde::{Deserialize, Serialize};

pub const SAFETY_TYPES: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "de.petermaurer.TransientPasteboardType",
    "Pasteboard generator type",
    "com.agilebits.onepassword",
    "net.antelle.keeweb",
];

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default)]
pub struct Settings {
    pub max_items: usize,
    pub retention_days: u16,
    pub poll_interval_ms: u64,
    pub enabled_types: Vec<String>,
    pub ignored_apps: Vec<String>,
    pub allowlist_apps: bool,
    pub ignored_types: Vec<String>,
    pub ignored_patterns: Vec<String>,
    pub paused: bool,
    pub import_digest: Option<String>,
}

impl Default for Settings {
    fn default() -> Self {
        Self {
            max_items: 200,
            retention_days: 7,
            poll_interval_ms: 500,
            enabled_types: SUPPORTED_TYPES.iter().map(|v| (*v).into()).collect(),
            ignored_apps: Vec::new(),
            allowlist_apps: false,
            ignored_types: vec!["com.typeit4me.clipping".into()],
            ignored_patterns: Vec::new(),
            paused: false,
            import_digest: None,
        }
    }
}

impl Settings {
    pub fn validate(&self) -> Result<()> {
        if !(1..=10_000).contains(&self.max_items)
            || !(1..=365).contains(&self.retention_days)
            || !(100..=5_000).contains(&self.poll_interval_ms)
            || self.enabled_types.len() > SUPPORTED_TYPES.len()
            || self
                .enabled_types
                .iter()
                .any(|t| !SUPPORTED_TYPES.contains(&t.as_str()))
            || self.ignored_apps.len() > 256
            || self.ignored_types.len() > 128
            || self.ignored_patterns.len() > 32
            || self
                .import_digest
                .as_ref()
                .is_some_and(|d| d.len() != 64 || !d.bytes().all(|b| b.is_ascii_hexdigit()))
            || self
                .ignored_apps
                .iter()
                .any(|v| v.is_empty() || v.len() > 255)
            || self
                .ignored_types
                .iter()
                .any(|v| v.is_empty() || v.len() > 255)
        {
            return Err(CoreError::InvalidInput);
        }
        for pattern in &self.ignored_patterns {
            if pattern.len() > 512 || Self::compile_pattern(pattern).is_err() {
                return Err(CoreError::InvalidInput);
            }
        }
        Ok(())
    }

    pub fn compile_pattern(pattern: &str) -> Result<regex::Regex> {
        RegexBuilder::new(pattern)
            .size_limit(1024 * 1024)
            .build()
            .map_err(|_| CoreError::InvalidInput)
    }

    pub fn ignores(&self, payload: &ClipboardPayload) -> Result<bool> {
        if self.paused {
            return Ok(true);
        }
        let listed = payload
            .source_app
            .as_ref()
            .is_some_and(|app| self.ignored_apps.contains(app));
        if (self.allowlist_apps && !listed) || (!self.allowlist_apps && listed) {
            return Ok(true);
        }
        if payload
            .advertised_types
            .iter()
            .map(String::as_str)
            .chain(payload.representations.iter().map(|r| r.uti.as_str()))
            .any(|t| SAFETY_TYPES.contains(&t) || self.ignored_types.iter().any(|v| v == t))
        {
            return Ok(true);
        }
        for pattern in &self.ignored_patterns {
            let compiled = Self::compile_pattern(pattern)?;
            if compiled.is_match(&payload.text)
                || payload
                    .representations
                    .iter()
                    .filter(|r| r.uti == TEXT)
                    .filter_map(|r| std::str::from_utf8(&r.data).ok())
                    .any(|text| compiled.is_match(text))
            {
                return Ok(true);
            }
        }
        Ok(false)
    }

    pub(crate) fn ignores_text(&self, text: &str) -> Result<bool> {
        for pattern in &self.ignored_patterns {
            if Self::compile_pattern(pattern)?.is_match(text) {
                return Ok(true);
            }
        }
        Ok(false)
    }
}
